import threading
import uuid

class Queue:
    def __init__(self):
        self._lock = threading.Lock()
        self._jobs = {}
        self._next_job_id = 0

    def add(self, job_id):
        with self._lock:
            self._jobs[job_id] = {'state': 'queued'}

    def claim(self, worker, now, ttl):
        with self._lock:
            for job_id in sorted(self._jobs.keys()):
                job = self._jobs[job_id]
                if job['state'] in ['queued', 'running'] and job.get('expiry', 0) <= now:
                    job['state'] = 'running'
                    job['worker'] = worker
                    job['expiry'] = now + ttl
                    job['token'] = str(uuid.uuid4())
                    return {'job_id': job_id, 'worker': worker, 'token': job['token']}
            return None

    def renew(self, lease, now, ttl):
        with self._lock:
            job_id = lease['job_id']
            job = self._jobs.get(job_id)
            if job and job['state'] == 'running' and job['worker'] == lease['worker'] and job['token'] == lease['token'] and job['expiry'] > now:
                job['expiry'] = now + ttl
                return True
            return False

    def complete(self, lease, now):
        with self._lock:
            job_id = lease['job_id']
            job = self._jobs.get(job_id)
            if job and job['state'] == 'running' and job['worker'] == lease['worker'] and job['token'] == lease['token'] and job['expiry'] > now:
                job['state'] = 'completed'
                return True
            return False
